"""
ProjectEuler.net #8

The four adjacent digits in the -digit number that have the greatest product are 9 * 9 * 8 * 9 = 5832.



Find the thirteen adjacent digits in the 13-digit number that have the greatest product. What is the value of this product?

Any string of 13 containing is instantly disqualified. We can split this number by the 0 character, then only check each substring.

For each non-zero substring, we can calculate the each set of 13 digits within it.
"""

DIGITS = 13
NUMBER = ''

def main():
	groups = NUMBER.split('0')
	result = 0
	for group in groups:
		if len(group) < DIGITS:
			continue # ignore if too small, this would be 0
		# Calculate group
		for offset in range(len(group) - DIGITS + 1):
			value = 1
			for i in range(DIGITS):
				v = int(group[offset + i])
				value *= v
			if value > result:
				result = value
	print(result)
	
if __name__=='__main__':
	main()